{
  "scenes": [
    {
      "scene_id": "S1",
      "name": "凌乱工位",
      "location": "办公室工位 / 家中书桌",
      "purpose": "制造共鸣：让观众认出自己的桌子"
    },
    {
      "scene_id": "S2",
      "name": "三分钟整理过程",
      "location": "同一张桌子，俯拍为主",
      "purpose": "展示可执行的三个步骤"
    },
    {
      "scene_id": "S3",
      "name": "整理后的专注状态",
      "location": "同一张桌子，人物开始工作",
      "purpose": "呈现结果，收束情绪"
    }
  ],
  "shots": [
    {
      "shot_id": "SH01",
      "scene": "S1",
      "description": "桌面特写俯拍：键盘旁堆着水杯、快递盒、三支散落的笔，画面略拥挤。"
    },
    {
      "shot_id": "SH02",
      "scene": "S1",
      "description": "人物中景，坐下后看了一眼桌面，轻轻叹了口气，手停在鼠标上没动。"
    },
    {
      "shot_id": "SH03",
      "scene": "S2",
      "description": "手部特写：把与工作无关的物品逐件移出画面边缘，桌面逐渐露出空白。"
    },
    {
      "shot_id": "SH04",
      "scene": "S2",
      "description": "俯拍全景，画面用三分法呈现左输入、中输出、右待办三个区域，配字幕标注。"
    },
    {
      "shot_id": "SH05",
      "scene": "S2",
      "description": "近景，一张纸被写下三行待办，笔尖停顿后画上对勾。"
    },
    {
      "shot_id": "SH06",
      "scene": "S2",
      "description": "湿巾擦过桌面的横向运镜，随后手指把充电线理顺成一束。"
    },
    {
      "shot_id": "SH07",
      "scene": "S3",
      "description": "固定全景：干净的桌面，人正面入画开始敲键盘，背景音渐入。"
    },
    {
      "shot_id": "SH08",
      "scene": "S3",
      "description": "侧面特写，人物专注的侧脸与屏幕倒影，最后一个字幕后灯渐暗。"
    }
  ]
}
